950	
951	  // Which MySQL-family engine to install on the target, from the DETECTED variant:
952	  // Oracle MySQL → mysql-server (clean same-engine); MariaDB (or undeterminable) →
953	  // mariadb-server (the existing safe default). This is a validated enum, never a
954	  // source string; it only selects a fixed package-allowlist KEY.
955	  const mysqlDetail = (scan.dbEngines ?? []).find((d) => d?.engine === "mysql");
956	  const mysqlVariant: "mysql" | "mariadb" = mysqlDetail?.variant === "mysql" ? "mysql" : "mariadb";
957	  const mysqlVersion: string | null = mysqlDetail?.version ?? null;
958	  const pgDetail = (scan.dbEngines ?? []).find((d) => d?.engine === "postgres");
959	  const pgVersion: string | null = pgDetail?.version ?? null;
960	
961	  const dockerVolumes = [...new Set(items.dockerVolumes ?? [])].filter((v) => VOLNAME_RE.test(v)).slice(0, 60);
962	  // Compose projects the scanner tagged (signature "compose") must be brought up
963	  // with `docker compose up`, not left to standalone container recreation. Their
964	  // running containers otherwise fall through to the standalone path (no compose
965	  // network / env-file / depends_on) and crash-loop — the /opt/soulpilates case
966	  // where 13 containers were "recreated" and 0 stayed up. `items.composeDirs` is
967	  // only populated on some scans, so union it with the compose-signature appDirs.
968	  const composeFromScan = (scan.appDirs ?? [])
969	    .filter((d) => d?.signature === "compose" && typeof d.path === "string" && d.path)
970	    .map((d) => String(d.path));
971	  const composeDirs = [...new Set([...(items.composeDirs ?? []), ...composeFromScan])].filter((p) => validPath(p)).slice(0, 40);
972	  const verifyPorts = [...new Set((items.verifyPorts ?? []).filter((p) => Number.isInteger(p) && p >= 1 && p <= 65535 && p !== 22))].slice(0, 60);
973	  const hasContainers = !!items.hasContainers || (scan.containers?.length ?? 0) > 0 || composeDirs.length > 0 || dockerVolumes.length > 0;
974	  const webServers = [...new Set(items.webServers ?? [])].filter((w): w is "nginx" | "apache" => w === "nginx" || w === "apache");
975	  const runtimes = [...new Set(items.runtimes ?? [])].filter((r): r is "nodejs" | "python3" => r === "nodejs" || r === "python3");
976	  const services = [...new Set((scan.services ?? []).map((s) => s?.name ?? "").filter((n) => SVCNAME_RE.test(n)))].slice(0, 30);
977	  // Timer-driven jobs (backups/maintenance). Threaded exactly like services: taken
978	  // from the stored scan, re-validated against SVCNAME_RE, capped. Each brings its
979	  // own `.timer` + backing `.service` across in the re-enable step.
980	  const timers = [...new Set((scan.timers ?? []).map((t) => t?.name ?? "").filter((n) => SVCNAME_RE.test(n)))].slice(0, 20);
981	  const containers = (scan.containers ?? [])
982	    .map((c) => ({
983	      name: String(c?.name ?? ""),
984	      image: String(c?.image ?? ""),
985	      ports: String(c?.ports ?? ""),
986	      mounts: Array.isArray(c?.mounts) ? c!.mounts!.map((m) => String(m)) : [],
987	    }))
988	    .slice(0, 30);
989	
990	  const prereqs: PkgKey[] = [];
991	  // Install the engine variant that MATCHES the source (Oracle MySQL vs MariaDB).
992	  if (dbEngines.includes("mysql")) prereqs.push(mysqlVariant === "mysql" ? "mysql_oracle" : "mysql");
993	  if (dbEngines.includes("postgres")) prereqs.push("postgresql");
994	  if (hasContainers) prereqs.push("docker");
995	  for (const w of webServers) prereqs.push(w === "nginx" ? "nginx" : "apache");
996	  for (const rt of runtimes) prereqs.push(rt);
997	
998	  return { dbEngines, mysqlVariant, mysqlVersion, pgVersion, dockerVolumes, composeDirs, verifyPorts, hasContainers, webServers, runtimes, services, timers, containers, prereqs };
