type ExecResult = { code: number; stdout: string; stderr: string };

/**
 * `execRemote` that never throws — a timed-out or broken command reports exit 1
 * with its reason in `stderr`. Every best-effort step uses this so one failed
 * probe can never abort the whole migration.
 */
function sh(conn: Client, cmd: string, timeoutMs: number = SETUP_TIMEOUT_MS): Promise<ExecResult> {
  return execRemote(conn, cmd, timeoutMs).catch((e) => ({
    code: 1,
    stdout: "",
    stderr: String(e?.message ?? e),
  }));
}

/** `sh` reduced to a boolean "did it succeed". */
async function shOk(conn: Client, cmd: string, timeoutMs: number = SETUP_TIMEOUT_MS): Promise<boolean> {
  return (await sh(conn, cmd, timeoutMs)).code === 0;
}

