// F5: `--single-transaction` gives a CONSISTENT snapshot for InnoDB ONLY;
// MyISAM (and other non-transactional engines) are NOT covered by it and
// tear if written during the dump. Cheaply ask information_schema (read-only,
// over the same root socket) whether any BASE TABLE in the user databases
// uses a non-InnoDB engine. If so, dump under a global read lock
// (`--lock-all-tables`, which is mutually exclusive with --single-transaction)
// so those tables are consistent too — but ONLY then, so the common
// InnoDB-only case keeps `--single-transaction` and takes no lock / no
// downtime. If engines can't be determined cheaply, keep the non-blocking
// path (`--single-transaction --quick`) and NAME that any MyISAM tables were
// copied without a lock.
const inList = dbList.map((d) => `'${d}'`).join(",");
const engQ = await sh(
  conn,
  onSource(`${priv}mysql -N -e "SELECT COUNT(*) FROM information_schema.tables WHERE table_schema IN (${inList}) AND table_type='BASE TABLE' AND engine IS NOT NULL AND engine <> 'InnoDB'"`),
  SETUP_TIMEOUT_MS,
);
const engN = Number(clean(engQ.stdout, 32));
let lockNote = "";
let dumpFlags: string;
if (engQ.code === 0 && Number.isFinite(engN)) {
  if (engN > 0) {
    // Non-InnoDB tables present → globally-consistent snapshot via read lock.
    dumpFlags = "--lock-all-tables --routines --triggers --events";
    lockNote = ` — ${engN} non-InnoDB (e.g. MyISAM) table(s) were present, so the dump used a brief global read lock for consistency`;
  } else {
    // InnoDB-only (the common case) — unchanged: no lock, no downtime.
    dumpFlags = "--single-transaction --routines --triggers --events";
  }
} else {
  // Couldn't determine engines cheaply — keep the non-blocking path but NAME it.
  dumpFlags = "--single-transaction --quick --routines --triggers --events";
  lockNote = " — table engines could not be verified, so any MyISAM tables were copied WITHOUT a lock and may be inconsistent; verify them after cutover";
}
// mysqldump over root's LOCAL socket auth (Debian/Ubuntu root = auth_socket),
// limited to the validated user DB names.
const dumpCmd = `${priv}mysqldump ${dumpFlags} --databases ${dbList.join(" ")}`;
const r = await execRemote(conn, `${onSource(dumpCmd)} > ${dump} 2>${work}/dumps/mysql.err`, TRANSFER_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));

