// A12: content paths this run has itself created/populated, so a later path
// landing in the same tree is never mistaken for pre-existing customer data.
const createdThisRun = new Set<string>();
for (const p of paths) {
  idx++;
  const dst = remapPaths[p] ?? p;
  const remapped = dst !== p;
  const destParent = remapped ? dst : parentDir(p);
  await execRemote(conn, `mkdir -p ${destParent}`, SETUP_TIMEOUT_MS);
  const pct = 28 + Math.round((idx / paths.length) * 22); // 28 → 50
  // A12: this rsync MERGES the source tree into the SAME path on the target
  // (`dst` === `p` unless remapped). On a NON-fresh target that path may already
  // hold a DIFFERENT customer's files; merging over them silently is data loss.
  // If the target path already exists AND is non-empty AND we did not create it
  // earlier in this same run, refuse and NAME it — unless the operator opted in
  // to overwrite. Empty/absent target (every fresh-server migration) proceeds
  // exactly as before. `dst` is a validated path (validPath / safeCopyTarget).
  // Note: for a remapped path `mkdir -p` above just created `dst` empty, so the
  // find below returns nothing and does NOT false-positive.
  let targetNonFresh = false;
  if (!createdThisRun.has(dst)) {
    const probe = await sh(
      conn,
      `if [ -d ${dst} ]; then ${priv}find ${dst} -mindepth 1 -print -quit 2>/dev/null; elif [ -e ${dst} ]; then echo x; fi`,
