    await report(pct, "Copying files…", `  MIGRATE_OVERWRITE_TARGET_DATA=1 — ${dst} already has files on the new server; overwriting.`);
  }
  await report(pct, "Copying files…", remapped ? `  rsync ${p} → ${dst} (remapped to avoid a collision)` : `  rsync ${p} → ${p}`);

