// ---- 8a. F4: host-native MongoDB & Redis — consistent capture ---------
// A MongoDB or Redis running on the SOURCE HOST (not in a container — those
// are handled by the F1 logical-dump path in step 7pre) keeps a LIVE datadir
// (/var/lib/mongodb WiredTiger, /var/lib/redis RDB/AOF). Before this, such a
// DB only moved if the operator hand-picked its datadir as a copy path — a hot
// file copy of a live datadir is torn/stale. So: detect it, take a CONSISTENT
// logical capture on the source, and restore it on the target. If we cannot
// capture consistently (tool absent, or auth required and unknown) we NEVER
// pretend a hot copy is good — we name the DB and that it needs a manual dump.
{
  // MongoDB: host-native if mongod is on the host PATH or /var/lib/mongodb exists
  // (a containerised mongo has neither on the host, so this won't double-handle it).
  const hostMongo = await shOk(conn, onSource("command -v mongod >/dev/null 2>&1 || test -d /var/lib/mongodb"), SETUP_TIMEOUT_MS);
  if (hostMongo) {
    await report(65, "Migrating databases…", "Detected MongoDB on the old server — taking a consistent dump (no torn datadir copy).");
    const hasDump = await shOk(conn, onSource("command -v mongodump >/dev/null 2>&1"), SETUP_TIMEOUT_MS);
    if (!hasDump) {
      push({ step: "Migrate MongoDB", status: "failed", detail: "MongoDB is running on the old server but `mongodump` is not installed there, so a consistent dump could NOT be taken — its data was NOT migrated. Install mongodb-database-tools on the old server, take `mongodump --archive` (with credentials if it needs auth), then restore here with `mongorestore --archive --drop`." });
    } else {
      const archive = `${work}/dumps/host-mongo.archive`;
      const errf = `${work}/dumps/host-mongo.err`;
      // Default no-auth for a host mongo. If the server requires auth, mongodump
      // produces nothing / errors → the honest-refuse below fires (we never guess
      // credentials, and never fall back to a torn hot copy).
      const r = await execRemote(conn, `${onSource("mongodump --archive")} > ${archive} 2>${errf}`, TRANSFER_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
      const nonEmpty = await shOk(conn, `test -s ${archive}`, SETUP_TIMEOUT_MS);
      if (r.code !== 0 || !nonEmpty) {
        const err = clean((await sh(conn, `tail -c 200 ${errf} 2>/dev/null`)).stdout, 200);
        push({ step: "Migrate MongoDB", status: "failed", detail: `a consistent MongoDB dump could not be taken from the old server${err ? ` (${err})` : ""} — most often the server requires authentication we do not have. Its data was NOT migrated; take a manual \`mongodump --archive\` (with --username/--password) on the old server and restore it here with \`mongorestore --archive --drop\`. The empty archive at ${archive} is safe to ignore.` });
      } else {
        // Ensure the target has mongorestore + mongod. Unlike redis-server, MongoDB
        // is NOT in stock apt, so install is best-effort; if it stays absent we
        // KEEP the good dump and honest-refuse rather than lose data.
        let haveTools = await shOk(conn, "command -v mongorestore >/dev/null 2>&1 && command -v mongod >/dev/null 2>&1");
        if (!haveTools) {
          await sh(conn, `DEBIAN_FRONTEND=noninteractive apt-get install -y mongodb-org mongodb-org-tools 2>/dev/null || DEBIAN_FRONTEND=noninteractive apt-get install -y mongodb mongo-tools 2>/dev/null || true`, INSTALL_TIMEOUT_MS);
          haveTools = await shOk(conn, "command -v mongorestore >/dev/null 2>&1 && command -v mongod >/dev/null 2>&1");
        }
        if (!haveTools) {
          push({ step: "Migrate MongoDB", status: "failed", detail: `a consistent MongoDB dump was taken and kept at ${archive}, but MongoDB is not installed on the new server and could not be installed automatically. Install MongoDB (mongodb-org) here, then restore with: mongorestore --archive --drop < ${archive}` });
        } else {
          await sh(conn, "systemctl enable --now mongod 2>/dev/null || systemctl enable --now mongodb 2>/dev/null || service mongod start 2>/dev/null || service mongodb start 2>/dev/null || true", SETUP_TIMEOUT_MS);
          // Wait (bounded) for mongod to accept connections before restoring.
          await sh(conn, "i=0; while [ $i -lt 15 ]; do (mongosh --quiet --eval 'db.adminCommand({ping:1})' >/dev/null 2>&1 || mongo --quiet --eval 'db.adminCommand({ping:1})' >/dev/null 2>&1) && break; i=$((i+1)); sleep 2; done", SETUP_TIMEOUT_MS);
          // Overwrite guard (A1-style): if the target mongo already holds a user
          // database and the operator did not opt in, do not `--drop` over it.
          let targetHasData = false;
          if (!OVERWRITE_TARGET_DATA) {
            const dbs = clean((await sh(conn, "mongosh --quiet --eval 'db.adminCommand({listDatabases:1}).databases.map(d=>d.name).filter(n=>[\"admin\",\"config\",\"local\"].indexOf(n)<0).join(\",\")' 2>/dev/null || mongo --quiet --eval 'db.adminCommand({listDatabases:1}).databases.map(function(d){return d.name}).filter(function(n){return [\"admin\",\"config\",\"local\"].indexOf(n)<0}).join(\",\")' 2>/dev/null")).stdout, 512);
            targetHasData = dbs.length > 0;
