        // gracefully (keep the snapshot) if it somehow stays absent.
        let haveRedis = await shOk(conn, "command -v redis-server >/dev/null 2>&1");
        if (!haveRedis) {
          await sh(conn, `DEBIAN_FRONTEND=noninteractive apt-get install -y redis-server 2>/dev/null || DEBIAN_FRONTEND=noninteractive apt-get install -y redis 2>/dev/null || true`, INSTALL_TIMEOUT_MS);
          haveRedis = await shOk(conn, "command -v redis-server >/dev/null 2>&1");
        }
        if (!haveRedis) {
          push({ step: "Migrate Redis", status: "failed", detail: `a consistent Redis snapshot was taken and kept at ${rdb}, but Redis is not installed on the new server and could not be installed automatically. Install redis-server here, then copy ${rdb} to /var/lib/redis/dump.rdb (owner redis:redis) and restart Redis.` });
        } else {
          // Overwrite guard (A1-style): a non-empty existing dump.rdb on the target
          // is the new server's own Redis data — don't clobber it unless opted in.
          const existing = await shOk(conn, "test -s /var/lib/redis/dump.rdb");
          if (existing && !OVERWRITE_TARGET_DATA) {
            push({ step: "Migrate Redis", status: "failed", detail: `the new server already has Redis data at /var/lib/redis/dump.rdb; not overwriting it — set MIGRATE_OVERWRITE_TARGET_DATA=1 to replace it, or migrate to a fresh server. The snapshot is kept at ${rdb}` });
            await report(66, "Migrating databases…", "  Redis import skipped — the new server already has Redis data (not overwriting).");
          } else {
            if (existing && OVERWRITE_TARGET_DATA) await report(66, "Migrating databases…", "  MIGRATE_OVERWRITE_TARGET_DATA=1 — replacing the new server's Redis data.");
