            await sh(conn, `mkdir -p /var/lib/redis && cp ${rdb} /var/lib/redis/dump.rdb && chown redis:redis /var/lib/redis/dump.rdb 2>/dev/null; chmod 660 /var/lib/redis/dump.rdb 2>/dev/null; true`, SETUP_TIMEOUT_MS);
            await sh(conn, "systemctl enable --now redis-server 2>/dev/null || systemctl enable --now redis 2>/dev/null || service redis-server start 2>/dev/null || service redis start 2>/dev/null || true", SETUP_TIMEOUT_MS);
            push({ step: "Migrate Redis", status: "copied", detail: "snapshotted consistently from the old server (redis-cli --rdb) and restored into the new server's Redis datadir; Redis restarted to load it. If your Redis uses AOF persistence, confirm appendonly is off (or rebuild the AOF) so the RDB is loaded." });
            await report(66, "Migrating databases…", "  Redis snapshot restored.");
          }
        }
      }
    }
  }
}

